		this.eInput = new InputElements();
		this.eOutput = new OutputElements();
		this.pData = new DataElements();
		this.pDataType = new DataTypeElements();
		this.pPropertyCategoryLibrary = new PropertyCategoryLibraryElements();
		this.pPropertyCategory = new PropertyCategoryElements();
		this.pPropertyDefinition = new PropertyDefinitionElements();
		this.pComplianceDefinition = new ComplianceDefinitionElements();
		this.pOverlayComplianceDeffinition = new OverlayComplianceDeffinitionElements();
		this.pOverlayInstance = new OverlayInstanceElements();
		this.pStandardRef = new StandardRefElements();
